import { useState, type FormEvent } from 'react';
import { JxStepper, JxInputField, JxButton } from '@jinx-ui/react';

type ContactData = {
  fullName: string;
  email: string;
};

type AddressData = {
  street: string;
  city: string;
  postalCode: string;
};

type RegistrationData = ContactData & AddressData;

const STEPS = [{ label: 'Контакты' }, { label: 'Адрес' }, { label: 'Проверка' }];

interface RegistrationWizardProps {
  onSubmit: (data: RegistrationData) => void;
}

export default function RegistrationWizard({ onSubmit }: RegistrationWizardProps) {
  const [step, setStep] = useState(0);
  const [contact, setContact] = useState<ContactData>({ fullName: '', email: '' });
  const [address, setAddress] = useState<AddressData>({ street: '', city: '', postalCode: '' });

  const emailError =
    contact.email.length > 0 && !contact.email.includes('@') ? 'Укажите адрес с символом @' : undefined;

  const isStepValid =
    step === 0
      ? contact.fullName.trim().length > 0 && contact.email.trim().length > 0 && !emailError
      : step === 1
      ? address.street.trim().length > 0 && address.city.trim().length > 0 && address.postalCode.trim().length > 0
      : true;

  const goBack = () => setStep((current) => Math.max(current - 1, 0));
  const goNext = () => setStep((current) => Math.min(current + 1, STEPS.length - 1));

  const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (step < STEPS.length - 1) {
      if (isStepValid) goNext();
      return;
    }
    onSubmit({ ...contact, ...address });
  };

  return (
    <form
      onSubmit={handleSubmit}
      style={{ display: 'flex', flexDirection: 'column', gap: 24, maxWidth: 420 }}
    >
      <JxStepper steps={STEPS} current={step} />

      {step === 0 && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
          <JxInputField
            label="Полное имя"
            required
            value={contact.fullName}
            onChange={(event) => setContact((prev) => ({ ...prev, fullName: event.target.value }))}
          />
          <JxInputField
            label="Электронная почта"
            type="email"
            required
            value={contact.email}
            onChange={(event) => setContact((prev) => ({ ...prev, email: event.target.value }))}
            errorText={emailError}
          />
        </div>
      )}

      {step === 1 && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
          <JxInputField
            label="Улица и дом"
            required
            value={address.street}
            onChange={(event) => setAddress((prev) => ({ ...prev, street: event.target.value }))}
          />
          <JxInputField
            label="Город"
            required
            value={address.city}
            onChange={(event) => setAddress((prev) => ({ ...prev, city: event.target.value }))}
          />
          <JxInputField
            label="Почтовый индекс"
            required
            value={address.postalCode}
            onChange={(event) => setAddress((prev) => ({ ...prev, postalCode: event.target.value }))}
          />
        </div>
      )}

      {step === 2 && (
        <dl style={{ display: 'flex', flexDirection: 'column', gap: 12, margin: 0 }}>
          <div>
            <dt style={{ color: 'var(--jx-text-2)', fontSize: '0.85em' }}>Полное имя</dt>
            <dd style={{ margin: 0, color: 'var(--jx-text)' }}>{contact.fullName || '—'}</dd>
          </div>
          <div>
            <dt style={{ color: 'var(--jx-text-2)', fontSize: '0.85em' }}>Электронная почта</dt>
            <dd style={{ margin: 0, color: 'var(--jx-text)' }}>{contact.email || '—'}</dd>
          </div>
          <div>
            <dt style={{ color: 'var(--jx-text-2)', fontSize: '0.85em' }}>Адрес</dt>
            <dd style={{ margin: 0, color: 'var(--jx-text)' }}>
              {address.street || '—'}, {address.city || '—'}, {address.postalCode || '—'}
            </dd>
          </div>
        </dl>
      )}

      <div style={{ display: 'flex', justifyContent: 'space-between', gap: 12 }}>
        <JxButton type="button" variant="ghost" disabled={step === 0} onClick={goBack}>
          Назад
        </JxButton>
        {step < STEPS.length - 1 ? (
          <JxButton type="submit" variant="primary" disabled={!isStepValid}>
            Дальше
          </JxButton>
        ) : (
          <JxButton type="submit" variant="primary">
            Отправить
          </JxButton>
        )}
      </div>
    </form>
  );
}

